# Cart: bridge -- "Rise for the Bridge"
#
# A prototype. You have no jump. The only way off the ground is to raise the
# dead underneath you: they come up out of the cemetery floor, hold for six
# seconds, then topple. The chasm is wider than one corpse, so you have to
# chain them and keep moving.
#
#   ./bin/run --cart bridge
#
# Controls: arrows / WASD / stick to run. SPACE (or A) raises the dead beneath
# you. There is no jump and there is no other verb.
#
# Zero art. Every texture is generated by auto_sprite at boot.
#
# NOTE ON THE STAGE: this cart draws in screen space and sizes its stage to the
# window on purpose. The whole chasm has to be legible at once -- reading which
# corpses you have already raised, and which are about to topple, IS the
# decision. A following camera would pan that away. It never calls camera.apply,
# so the camera transform is a no-op here and this costs nothing.
TITLE = 'rise for the bridge'

class Bridge
  LEDGE_W = 280  # width of the solid ground at each end
  LEDGE_H = 200  # and its height -- also the depth of the chasm, so a corpse
                  # rising out of the pit floor comes up flush with the ground
  PIT_W   = 28   # a corpse's width
  PIT_H   = 200  # and its height. Flush with the ledges, so it is a floor and
                  # not a wall -- there is no jump in this game.
  RISE    = 10   # ticks for a corpse to come up out of the dirt
  TOPPLE  = 360  # 6 seconds at 60fps
  SPEED   = 5.0
  GRAVITY = 0.5
  FALL    = 200  # below this you are in the pit for good

  def setup
    auto_sprite :hero,  20,     28,       :accent,  :frame
    auto_sprite :grave, PIT_W,  8,        :muted,   :solid
    auto_sprite :soul,  PIT_W,  PIT_H,    :accent2, :circle
    auto_sprite :dust,  6,      6,        :warn,    :checker

    scene :play, PlayScene
    scene :over, OverScene
    goto :play
  end

  class PlayScene
    def enter
      Console.entities.clear
      Console.tweens.clear
      Console.anim.stop_all

      # The stage is the window. Screen space only -- see the note in main.rb.
      @sw = screen[:w]
      @sh = screen[:h]
      @left  = { x: 0, y: 0, w: Bridge::LEDGE_W, h: Bridge::LEDGE_H }
      @right = { x: @sw - Bridge::LEDGE_W, y: 0, w: Bridge::LEDGE_W, h: Bridge::LEDGE_H }
      @pit_l = @left[:x] + @left[:w]
      @pit_r = @right[:x]
      @goal_x = @right[:x] + 70

      d = scene_data
      d[:raised] = 0
      d[:won]    = false

      # The ledges are level geometry; corpses join the collision as solid
      # entities when they are raised, and leave it when they are despawned.
      world_solids [@left, @right]

      @hero = spawn :hero, kind: :hero, x: 110, y: 320, w: 20, h: 28, sprite: :hero,
                           body: { gravity: Bridge::GRAVITY, step_height: 8 }
      @body = @hero[:body]
    end

    def update
      run
      raise_dead
      topple
      cull
      finish
    end

    def render
      background :panel_d

      draw_pit
      draw_ledges
      draw_graves
      each_entity { |e| draw_entity e }

      hud
    end

    private

    # The body is stepped by the console before update, so this only sets
    # intent for the next frame.
    def run
      @body.vx = input.axis_x * Bridge::SPEED
    end

    def standing_planks
      entities_of(:plank).select { |p| p[:solid] }
    end

    def raise_dead
      return unless input.pressed?(:accept) || input.pressed?(:action_2)

      x = @body.x
      cy = @body.y + (@body.h / 2.0)

      # You cannot raise through solid ground, and only inside the chasm.
      return if inside?(@left, x, cy) || inside?(@right, x, cy)
      return if x < @pit_l || x > @pit_r

      # One corpse per spot -- no stacking into a pillar.
      return if standing_planks.any? { |p| (p[:x] + (p[:w] / 2.0) - x).abs < Bridge::PIT_W }

      # The corpse IS the collision: a solid entity, so tweening its h grows
      # the sprite and the rect the hero stands on together.
      e = spawn :soul, kind: :plank,
                x: x - (Bridge::PIT_W / 2.0), y: 0,
                w: Bridge::PIT_W, h: 0,
                sprite: :soul, alpha: 255,
                solid: true, t: Bridge::TOPPLE

      tween e, :h, to: Bridge::PIT_H, in: Bridge::RISE, ease: :out

      scene_data[:raised] += 1
      camera.shake 5, 10
      sfx :land
      dust x, 0
    end

    def topple
      standing_planks.each do |p|
        p[:t] -= 1
        next if p[:t] > 0

        # No longer solid the moment it starts to fall, so the hero drops
        # rather than riding the toppling corpse down.
        p[:solid] = false
        tween p, :alpha, to: 0, in: 14, ease: :in
        tween p, :y, to: -Bridge::PIT_H, in: 14, ease: :in
        after 14 { despawn p }
        camera.shake 6, 12
        sfx :hit
      end
    end

    # EntityStore holds no velocity and no lifetime of its own; both are manual.
    def cull
      each_entity(:dust) do |e|
        move e, vx: e[:vx], vy: e[:vy]
        e[:life] -= 1
      end
      despawn_if { |e| e[:kind] == :dust && e[:life] <= 0 }
    end

    def finish
      if @body.y < -Bridge::FALL
        scene_data[:won] = false
        goto :over
      elsif @body.x > @goal_x
        scene_data[:won] = true
        goto :over
      end
    end

    def dust(x, y)
      8.times do
        spawn :dust, kind: :dust, x: x + rand_between(-10, 10), y: y,
                     w: 6, h: 6, sprite: :dust,
                     vx: rand_between(-2, 2), vy: rand_between(0.5, 2.5),
                     tint: :warn, life: 24
      end
    end

    # The pit is drawn as a darker void behind everything, so the chasm reads
    # as depth rather than as "the ground simply stopped".
    def draw_pit
      draw.rect x: @pit_l, y: 0, w: @pit_r - @pit_l, h: Bridge::LEDGE_H,
                color: :black, alpha: 120
    end

    def draw_ledges
      draw.rect x: @left[:x],  y: @left[:y],  w: @left[:w],  h: @left[:h],
                color: :panel
      draw.rect x: @right[:x], y: @right[:y], w: @right[:w], h: @right[:h],
                color: :panel
      # The far edge, so the player knows where they are going.
      draw.rect x: @goal_x, y: Bridge::LEDGE_H - 60, w: 6, h: 60,
                color: :good
      draw.rect x: @right[:x], y: Bridge::LEDGE_H, w: @right[:w], h: 4,
                color: :good
    end

    # Grave markers along the pit floor: the affordance, made visible.
    def draw_graves
      x = @pit_l + 20
      while x < @pit_r
        draw.sprite path: :grave, x: x, y: 0, w: Bridge::PIT_W, h: 8
        x += 90
      end
    end

    def hud
      d = scene_data
      draw.within strip(0, 48) do
        draw.rect place: { x: 0, y: 0, w: 1, h: 1 }, color: :black, alpha: 170
        draw.text "RAISED #{d[:raised]}",
                  place: { x: 0.02, y: 0.5, anchor_y: 0.5 }, color: :text
        draw.text 'ARROWS run     SPACE raise the dead',
                  place: { x: 0.5, y: 0.5, anchor_x: 0.5, anchor_y: 0.5 },
                  color: :muted
      end
    end
  end

  # Uses goto, not push_scene/pop_scene. pop_scene currently nils
  # @current_instance without re-activating the scene underneath (scene.rb:293),
  # so every later dispatch hits `return unless inst.respond_to?(hook)` on nil
  # and the screen freezes instead of redrawing. `goto` replaces the stack and
  # activates properly, which is also what arcade's game-over screen does.
  class OverScene
    def enter
      sfx :gameover
    end

    def update
      goto :play if input.pressed?(:accept)
    end

    def render
      # Deliberately NOT Console.scenes.draw_below: that constructs a FRESH
      # instance of the scene underneath (scene.rb:268, `d.klass.new`) instead
      # of reusing the live one, so its render hook sees nil state and dies.
      # ui.card dims the screen on its own, so nothing is lost here.
      d = scene_data(:play)
      card = Console.ui.card w: 460, h: 240

      Console.draw.text(d[:won] ? 'THE FAR SIDE' : 'INTO THE PIT',
                        x: card[:x] + (card[:w] / 2.0),
                        y: card[:y] + card[:h] - 80,
                        anchor_x: 0.5, size_px: 34,
                        color: d[:won] ? :accent : :bad)

      Console.draw.text("raised #{d[:raised]}",
                        x: card[:x] + (card[:w] / 2.0),
                        y: card[:y] + 95, anchor_x: 0.5, color: :text)

      Console.draw.text('press space to try again',
                        x: card[:x] + (card[:w] / 2.0),
                        y: card[:y] + 40, anchor_x: 0.5, color: :muted)
    end
  end
end

# ---------------------------------------------------------------------------
# WHY THIS CART LOOKS THE WAY IT DOES
#
# 1. Screen-space staging with no camera.follow -- see the note at the top. A
#    following camera would pan away the corpses you already raised, and
#    reading which ones are about to topple is the entire decision.
#
# 2. Scene changes use goto, not push_scene/pop_scene. (This was once a
#    workaround: pop_scene used to freeze the screen and draw_below built a
#    fresh, empty instance. Both are fixed -- pop resumes the cached instance --
#    so goto is now simply the fit for a game with no pause overlay.)
# ---------------------------------------------------------------------------